    if (response.status != 200) {
        console.log(chalk.cyan(`෴   status: `) + response.code);
    }else{
        console.log(chalk.yellow(`෴   status:`) + response.code);
    }
    console.log(chalk.cyan(`෴   time: `) + response.responseTime);
    console.log(chalk.cyan(`\n`));

});
